"use client";

import React from "react";
import { useParams, useRouter } from "next/navigation";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { 
  ArrowLeft, 
  Mail,
  Phone,
  MapPin,
  Calendar,
  DollarSign,
  Briefcase,
  Building2,
  User,
  Shield,
  AlertCircle,
  Heart,
  Code,
  Edit,
  Download,
  RotateCcw,
  FlipHorizontal,
  FileText,
  X
} from "lucide-react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { useGetOurTeamByIdQuery } from "@/api/admin/our-team/ourTeamApi";
import { useGetDepartmentsQuery } from "@/api/landing/department/departmentApi";
import Link from "next/link";
import IDCard from "@/components/admin/our-team/IDCard";
import IDCardA4Page from "@/components/admin/our-team/IDCardA4Page";
import { useRef, useState } from "react";
import html2canvas from "html2canvas-pro";
import { toast } from "sonner";

export default function OurTeamDetailPage() {
  const params = useParams();
  const router = useRouter();
  const teamMemberId = params.id;
  const idCardFrontRef = useRef(null);
  const idCardBackRef = useRef(null);
  const idCardA4Ref = useRef(null);
  const [cardSide, setCardSide] = useState("front"); // "front" or "back"
  const [showA4Preview, setShowA4Preview] = useState(false);

  const { data: teamMemberData, isLoading, error } = useGetOurTeamByIdQuery(teamMemberId);
  const { data: departmentsData } = useGetDepartmentsQuery();

  const teamMember = teamMemberData?.data || teamMemberData;
  const departments = departmentsData?.data || departmentsData || [];

  if (isLoading) {
    return (
      <div className="max-w-[1600px] w-full mx-auto px-4 py-8">
        <div className="flex items-center justify-center h-96">
          <div className="text-center">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-gray-900 mx-auto mb-4"></div>
            <p className="text-gray-500">Loading team member details...</p>
          </div>
        </div>
      </div>
    );
  }

  if (error || !teamMember) {
    return (
      <div className="max-w-[1600px] w-full mx-auto px-4 py-8">
        <div className="flex items-center justify-center h-96">
          <div className="text-center">
            <p className="text-red-500 mb-4">Failed to load team member</p>
            <Button onClick={() => router.back()} variant="outline">
              <ArrowLeft className="w-4 h-4 mr-2" />
              Go Back
            </Button>
          </div>
        </div>
      </div>
    );
  }

  const getDepartmentName = () => {
    if (!teamMember.departmentId) return "No Department";
    const department = departments.find((dept) => (dept.id || dept._id) === teamMember.departmentId);
    return department?.name || `Department #${teamMember.departmentId}`;
  };

  const getStatusBadge = (status) => {
    const statusConfig = {
      active: { label: "Active", variant: "default", className: "bg-green-100 text-green-700" },
      inactive: { label: "Inactive", variant: "secondary", className: "bg-gray-100 text-gray-700" },
      "on-leave": { label: "On Leave", variant: "secondary", className: "bg-yellow-100 text-yellow-700" },
    };
    const config = statusConfig[status] || statusConfig.inactive;
    return (
      <Badge className={config.className}>
        {config.label}
      </Badge>
    );
  };

  const getRoleBadge = (role) => {
    const roleConfig = {
      Employee: { className: "bg-blue-100 text-blue-700" },
      Manager: { className: "bg-purple-100 text-purple-700" },
      Admin: { className: "bg-red-100 text-red-700" },
      HR: { className: "bg-orange-100 text-orange-700" },
    };
    const config = roleConfig[role] || roleConfig.Employee;
    return (
      <Badge className={config.className}>
        {role}
      </Badge>
    );
  };

  const fullName = `${teamMember.firstName || ""} ${teamMember.lastName || ""}`.trim();
  const initials = `${teamMember.firstName?.[0] || ""}${teamMember.lastName?.[0] || ""}`.toUpperCase();

  const handleDownloadIDCard = async (side = cardSide) => {
    const idCardRef = side === "front" ? idCardFrontRef : idCardBackRef;
    if (!idCardRef.current) return;

    try {
      toast.loading(`Generating ID card ${side}...`, { id: "download-id" });
      
      // Create a completely isolated iframe to avoid any CSS inheritance
      const iframe = document.createElement('iframe');
      iframe.style.cssText = `
        position: fixed;
        left: -9999px;
        top: 0;
        width: 400px;
        height: 250px;
        border: none;
      `;
      document.body.appendChild(iframe);

      // Wait for iframe to load
      await new Promise((resolve) => {
        iframe.onload = resolve;
        iframe.src = 'about:blank';
      });

      const iframeDoc = iframe.contentDocument || iframe.contentWindow.document;
      
      // Create a minimal HTML structure with only inline styles
      iframeDoc.open();
      iframeDoc.write(`
        <!DOCTYPE html>
        <html>
          <head>
            <style>
              * {
                margin: 0;
                padding: 0;
                box-sizing: border-box;
              }
              body {
                margin: 0;
                padding: 0;
                font-family: system-ui, -apple-system, sans-serif;
                background: transparent;
              }
            </style>
          </head>
          <body></body>
        </html>
      `);
      iframeDoc.close();

      // Clone the card and remove all problematic attributes
      const cardClone = idCardRef.current.cloneNode(true);
      
      // Recursively clean the clone
      const cleanElement = (el) => {
        if (el.nodeType === Node.ELEMENT_NODE) {
          // Remove all attributes except style and id
          const attrsToKeep = ['style', 'id', 'src', 'alt'];
          Array.from(el.attributes).forEach(attr => {
            if (!attrsToKeep.includes(attr.name)) {
              el.removeAttribute(attr.name);
            }
          });
          
          // Process children
          Array.from(el.children).forEach(cleanElement);
        }
      };
      cleanElement(cardClone);
      
      iframeDoc.body.appendChild(cardClone);

      // Wait for rendering
      await new Promise(resolve => setTimeout(resolve, 200));

      // html2canvas-pro should handle modern color functions
      const canvas = await html2canvas(iframeDoc.body, {
        backgroundColor: null,
        scale: 2,
        logging: false,
        useCORS: true,
        allowTaint: true,
        windowWidth: 400,
        windowHeight: 250,
      });

      // Clean up
      document.body.removeChild(iframe);

      const imageUrl = canvas.toDataURL("image/png");
      const link = document.createElement("a");
      link.download = `${teamMember.employeeId || fullName.replace(/\s+/g, "_")}_ID_Card_${side}.png`;
      link.href = imageUrl;
      link.click();

      toast.success(`ID card ${side} downloaded successfully!`, { id: "download-id" });
    } catch (error) {
      console.error("Error generating ID card:", error);
      toast.error("Failed to download ID card", { id: "download-id" });
    }
  };

  const handleDownloadBothSides = async () => {
    await handleDownloadIDCard("front");
    await new Promise(resolve => setTimeout(resolve, 500));
    await handleDownloadIDCard("back");
  };

  const handleDownloadA4Page = async () => {
    if (!idCardA4Ref.current) return;

    try {
      toast.loading("Generating A4 page...", { id: "download-a4" });
      
      // Create a completely isolated iframe to avoid any CSS inheritance
      const iframe = document.createElement('iframe');
      iframe.style.cssText = `
        position: fixed;
        left: -9999px;
        top: 0;
        width: 210mm;
        height: 297mm;
        border: none;
      `;
      document.body.appendChild(iframe);

      // Wait for iframe to load
      await new Promise((resolve) => {
        iframe.onload = resolve;
        iframe.src = 'about:blank';
      });

      const iframeDoc = iframe.contentDocument || iframe.contentWindow.document;
      
      // Create a minimal HTML structure with only inline styles
      iframeDoc.open();
      iframeDoc.write(`
        <!DOCTYPE html>
        <html>
          <head>
            <style>
              * {
                margin: 0;
                padding: 0;
                box-sizing: border-box;
              }
              body {
                margin: 0;
                padding: 0;
                font-family: system-ui, -apple-system, sans-serif;
                background: #ffffff;
              }
              @media print {
                @page {
                  size: A4;
                  margin: 0;
                }
              }
            </style>
          </head>
          <body></body>
        </html>
      `);
      iframeDoc.close();

      // Clone the A4 page and remove all problematic attributes
      const pageClone = idCardA4Ref.current.cloneNode(true);
      
      // Recursively clean the clone
      const cleanElement = (el) => {
        if (el.nodeType === Node.ELEMENT_NODE) {
          // Remove all attributes except style and id
          const attrsToKeep = ['style', 'id', 'src', 'alt'];
          Array.from(el.attributes).forEach(attr => {
            if (!attrsToKeep.includes(attr.name)) {
              el.removeAttribute(attr.name);
            }
          });
          
          // Process children
          Array.from(el.children).forEach(cleanElement);
        }
      };
      cleanElement(pageClone);
      
      iframeDoc.body.appendChild(pageClone);

      // Wait for rendering
      await new Promise(resolve => setTimeout(resolve, 300));

      // html2canvas-pro should handle modern color functions
      const canvas = await html2canvas(iframeDoc.body, {
        backgroundColor: '#ffffff',
        scale: 2,
        logging: false,
        useCORS: true,
        allowTaint: true,
        windowWidth: 794, // A4 width in pixels at 96 DPI
        windowHeight: 1123, // A4 height in pixels at 96 DPI
      });

      // Clean up
      document.body.removeChild(iframe);

      const imageUrl = canvas.toDataURL("image/png");
      const link = document.createElement("a");
      link.download = `${teamMember.employeeId || fullName.replace(/\s+/g, "_")}_ID_Card_A4.png`;
      link.href = imageUrl;
      link.click();

      toast.success("A4 page downloaded successfully!", { id: "download-a4" });
    } catch (error) {
      console.error("Error generating A4 page:", error);
      toast.error("Failed to download A4 page", { id: "download-a4" });
    }
  };

  return (
    <div className="max-w-[1600px] w-full mx-auto px-4 py-8">
      {/* Header with Back Button and Actions */}
      <div className="flex items-center justify-between mb-6">
        <Button 
          variant="ghost" 
          onClick={() => router.back()} 
          className="gap-2"
        >
          <ArrowLeft className="w-4 h-4" />
          Back to Team Members
        </Button>
        <div className="flex items-center gap-2">
          <Button 
            variant="outline" 
            className="gap-2"
            onClick={() => handleDownloadIDCard(cardSide)}
          >
            <Download className="w-4 h-4" />
            Download {cardSide === "front" ? "Front" : "Back"}
          </Button>
          <Button 
            variant="outline" 
            className="gap-2"
            onClick={handleDownloadBothSides}
          >
            <Download className="w-4 h-4" />
            Download Both
          </Button>
          <Button 
            variant="default" 
            className="gap-2"
            onClick={handleDownloadA4Page}
          >
            <Download className="w-4 h-4" />
            Download A4 Page
          </Button>
          <Link href={`/admin/our-team?edit=${teamMemberId}`}>
            <Button variant="outline" className="gap-2">
              <Edit className="w-4 h-4" />
              Edit Member
            </Button>
          </Link>
        </div>
      </div>


      {/* Hero Section with Profile */}
      <Card className="mb-6 overflow-hidden">
        <div className="bg-gradient-to-r from-blue-500 to-purple-600 p-8">
          <div className="flex items-start gap-6">
            <Avatar className="w-32 h-32 border-4 border-white shadow-lg">
              <AvatarImage src={teamMember.profileImage} alt={fullName} />
              <AvatarFallback className="text-3xl bg-white text-gray-700">
                {initials}
              </AvatarFallback>
            </Avatar>
            <div className="flex-1 text-white">
              <div className="flex items-center gap-3 mb-3">
                {getStatusBadge(teamMember.status)}
                {getRoleBadge(teamMember.role)}
              </div>
              <h1 className="text-4xl font-bold mb-2">{fullName}</h1>
              {teamMember.position && (
                <p className="text-xl text-white/90 mb-2">{teamMember.position}</p>
              )}
              {teamMember.employeeId && (
                <p className="text-lg text-white/80">ID: {teamMember.employeeId}</p>
              )}
            </div>
          </div>
        </div>
      </Card>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Main Content */}
        <div className="lg:col-span-2 space-y-6">
          {/* Basic Information */}
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <User className="w-5 h-5" />
                Basic Information
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="flex items-start gap-3">
                  <Mail className="w-5 h-5 text-gray-400 mt-1" />
                  <div>
                    <p className="text-sm text-gray-500">Email</p>
                    <p className="font-medium">{teamMember.email || "N/A"}</p>
                  </div>
                </div>
                <div className="flex items-start gap-3">
                  <Phone className="w-5 h-5 text-gray-400 mt-1" />
                  <div>
                    <p className="text-sm text-gray-500">Phone</p>
                    <p className="font-medium">{teamMember.phone || "N/A"}</p>
                  </div>
                </div>
                {teamMember.dateOfBirth && (
                  <div className="flex items-start gap-3">
                    <Calendar className="w-5 h-5 text-gray-400 mt-1" />
                    <div>
                      <p className="text-sm text-gray-500">Date of Birth</p>
                      <p className="font-medium">
                        {new Date(teamMember.dateOfBirth).toLocaleDateString()}
                      </p>
                    </div>
                  </div>
                )}
                {teamMember.hireDate && (
                  <div className="flex items-start gap-3">
                    <Calendar className="w-5 h-5 text-gray-400 mt-1" />
                    <div>
                      <p className="text-sm text-gray-500">Hire Date</p>
                      <p className="font-medium">
                        {new Date(teamMember.hireDate).toLocaleDateString()}
                      </p>
                    </div>
                  </div>
                )}
              </div>
            </CardContent>
          </Card>

          {/* Employment Information */}
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Briefcase className="w-5 h-5" />
                Employment Information
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="flex items-start gap-3">
                  <Briefcase className="w-5 h-5 text-gray-400 mt-1" />
                  <div>
                    <p className="text-sm text-gray-500">Position</p>
                    <p className="font-medium">{teamMember.position || "N/A"}</p>
                  </div>
                </div>
                <div className="flex items-start gap-3">
                  <Shield className="w-5 h-5 text-gray-400 mt-1" />
                  <div>
                    <p className="text-sm text-gray-500">Role</p>
                    <div className="mt-1">
                      {getRoleBadge(teamMember.role)}
                    </div>
                  </div>
                </div>
                <div className="flex items-start gap-3">
                  <Building2 className="w-5 h-5 text-gray-400 mt-1" />
                  <div>
                    <p className="text-sm text-gray-500">Department</p>
                    <p className="font-medium">{getDepartmentName()}</p>
                  </div>
                </div>
                {teamMember.salary && (
                  <div className="flex items-start gap-3">
                    <DollarSign className="w-5 h-5 text-gray-400 mt-1" />
                    <div>
                      <p className="text-sm text-gray-500">Salary</p>
                      <p className="font-medium">
                        ${teamMember.salary.toLocaleString()}
                      </p>
                    </div>
                  </div>
                )}
              </div>
            </CardContent>
          </Card>

          {/* Address Information */}
          {(teamMember.address || teamMember.city || teamMember.state || teamMember.country) && (
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <MapPin className="w-5 h-5" />
                  Address Information
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="flex items-start gap-3">
                  <MapPin className="w-5 h-5 text-gray-400 mt-1" />
                  <div className="space-y-1">
                    {teamMember.address && <p className="font-medium">{teamMember.address}</p>}
                    <p className="text-gray-700">
                      {[
                        teamMember.city,
                        teamMember.state,
                        teamMember.zipCode,
                        teamMember.country
                      ].filter(Boolean).join(", ")}
                    </p>
                  </div>
                </div>
              </CardContent>
            </Card>
          )}

          {/* Emergency Contact */}
          {(teamMember.emergencyContactName || teamMember.emergencyContactPhone) && (
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <AlertCircle className="w-5 h-5" />
                  Emergency Contact
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {teamMember.emergencyContactName && (
                    <div className="flex items-start gap-3">
                      <User className="w-5 h-5 text-gray-400 mt-1" />
                      <div>
                        <p className="text-sm text-gray-500">Contact Name</p>
                        <p className="font-medium">{teamMember.emergencyContactName}</p>
                      </div>
                    </div>
                  )}
                  {teamMember.emergencyContactPhone && (
                    <div className="flex items-start gap-3">
                      <Phone className="w-5 h-5 text-gray-400 mt-1" />
                      <div>
                        <p className="text-sm text-gray-500">Contact Phone</p>
                        <p className="font-medium">{teamMember.emergencyContactPhone}</p>
                      </div>
                    </div>
                  )}
                </div>
              </CardContent>
            </Card>
          )}

          {/* Bio */}
          {teamMember.bio && (
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <User className="w-5 h-5" />
                  Biography
                </CardTitle>
              </CardHeader>
              <CardContent>
                <p className="text-gray-700 leading-relaxed">{teamMember.bio}</p>
              </CardContent>
            </Card>
          )}

          {/* Skills */}
          {teamMember.skills && Array.isArray(teamMember.skills) && teamMember.skills.length > 0 && (
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Code className="w-5 h-5" />
                  Skills
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="flex flex-wrap gap-2">
                  {teamMember.skills.map((skill, index) => (
                    <Badge key={index} variant="secondary" className="text-sm">
                      {skill}
                    </Badge>
                  ))}
                </div>
              </CardContent>
            </Card>
          )}
        </div>

        {/* Sidebar */}
        <div className="space-y-6">
          {/* ID Card Preview */}
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center justify-between">
                <span>ID Card</span>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => setCardSide(cardSide === "front" ? "back" : "front")}
                  className="gap-2"
                >
                  <FlipHorizontal className="w-4 h-4" />
                  {cardSide === "front" ? "Back" : "Front"}
                </Button>
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="flex justify-center mb-4">
                <div>
                  {/* Front Card */}
                  <div ref={idCardFrontRef} style={{ display: cardSide === "front" ? "block" : "none" }}>
                    <IDCard 
                      teamMember={teamMember} 
                      departmentName={getDepartmentName()}
                      side="front"
                    />
                  </div>
                  {/* Back Card */}
                  <div ref={idCardBackRef} style={{ display: cardSide === "back" ? "block" : "none" }}>
                    <IDCard 
                      teamMember={teamMember} 
                      departmentName={getDepartmentName()}
                      side="back"
                    />
                  </div>
                </div>
              </div>
              <div className="space-y-2">
                <Button 
                  className="w-full" 
                  onClick={() => handleDownloadIDCard(cardSide)}
                  variant="outline"
                >
                  <Download className="w-4 h-4 mr-2" />
                  Download {cardSide === "front" ? "Front" : "Back"}
                </Button>
                <Button 
                  className="w-full" 
                  onClick={handleDownloadBothSides}
                  variant="outline"
                >
                  <Download className="w-4 h-4 mr-2" />
                  Download Both Sides
                </Button>
                <Button 
                  className="w-full" 
                  onClick={handleDownloadA4Page}
                  variant="default"
                >
                  <Download className="w-4 h-4 mr-2" />
                  Download A4 Page (Both Sides)
                </Button>
              </div>
            </CardContent>
          </Card>

          {/* A4 Page Preview Button */}
          <Card>
            <CardHeader>
              <CardTitle>A4 Page Layout</CardTitle>
            </CardHeader>
            <CardContent>
              <Button 
                className="w-full" 
                onClick={() => setShowA4Preview(true)}
                variant="outline"
              >
                <FileText className="w-4 h-4 mr-2" />
                Preview A4 Page
              </Button>
            </CardContent>
          </Card>

      {/* A4 Page Preview Dialog */}
      <Dialog open={showA4Preview} onOpenChange={setShowA4Preview}>
        <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle className="flex items-center justify-between">
              <span>A4 Page Preview</span>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setShowA4Preview(false)}
              >
                <X className="w-4 h-4" />
              </Button>
            </DialogTitle>
          </DialogHeader>
          <div className="flex justify-center p-4 bg-gray-100">
            <div ref={idCardA4Ref} style={{ transform: 'scale(0.7)', transformOrigin: 'top center' }}>
              <IDCardA4Page 
                teamMember={teamMember} 
                departmentName={getDepartmentName()}
              />
            </div>
          </div>
          <div className="flex justify-end gap-2 pt-4 border-t">
            <Button variant="outline" onClick={() => setShowA4Preview(false)}>
              Close
            </Button>
            <Button onClick={handleDownloadA4Page}>
              <Download className="w-4 h-4 mr-2" />
              Download A4 Page
            </Button>
          </div>
        </DialogContent>
      </Dialog>

          {/* Status Card */}
          <Card>
            <CardHeader>
              <CardTitle>Status</CardTitle>
            </CardHeader>
            <CardContent className="space-y-3">
              <div>
                <p className="text-sm text-gray-500 mb-2">Current Status</p>
                {getStatusBadge(teamMember.status)}
              </div>
              <div>
                <p className="text-sm text-gray-500 mb-2">Role</p>
                {getRoleBadge(teamMember.role)}
              </div>
              {teamMember.employeeId && (
                <div>
                  <p className="text-sm text-gray-500 mb-1">Employee ID</p>
                  <p className="font-medium">{teamMember.employeeId}</p>
                </div>
              )}
            </CardContent>
          </Card>

          {/* Quick Info */}
          <Card>
            <CardHeader>
              <CardTitle>Quick Info</CardTitle>
            </CardHeader>
            <CardContent className="space-y-3 text-sm">
              {teamMember.hireDate && (
                <div>
                  <p className="text-gray-500 mb-1">Hire Date</p>
                  <p className="font-medium">
                    {new Date(teamMember.hireDate).toLocaleDateString()}
                  </p>
                </div>
              )}
              {teamMember.departmentId && (
                <div>
                  <p className="text-gray-500 mb-1">Department</p>
                  <p className="font-medium">{getDepartmentName()}</p>
                </div>
              )}
              {teamMember.salary && (
                <div>
                  <p className="text-gray-500 mb-1">Salary</p>
                  <p className="font-medium">${teamMember.salary.toLocaleString()}</p>
                </div>
              )}
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}
