"use client";

import React from "react";

export default function IDCard({ teamMember, departmentName, side = "front" }) {
  const fullName = `${teamMember.firstName || ""} ${teamMember.lastName || ""}`.trim();
  const initials = `${teamMember.firstName?.[0] || ""}${teamMember.lastName?.[0] || ""}`.toUpperCase();

  const getStatusBadge = (status) => {
    const statusConfig = {
      active: { label: "Active", bgColor: "#22c55e", textColor: "#ffffff" },
      inactive: { label: "Inactive", bgColor: "#6b7280", textColor: "#ffffff" },
      "on-leave": { label: "On Leave", bgColor: "#eab308", textColor: "#ffffff" },
    };
    const config = statusConfig[status] || statusConfig.inactive;
    return (
      <span 
        style={{ 
          backgroundColor: config.bgColor, 
          color: config.textColor,
          fontSize: '10px',
          padding: '2px 6px',
          borderRadius: '4px',
          display: 'inline-flex',
          alignItems: 'center',
          fontWeight: 600
        }}
      >
        {config.label}
      </span>
    );
  };

  // Front Side Design
  if (side === "front") {
    return (
      <div
        id="id-card-front"
        style={{
          width: '400px',
          height: '250px',
          borderRadius: '8px',
          boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.25)',
          overflow: 'hidden',
          position: 'relative',
          fontFamily: 'system-ui, -apple-system, sans-serif',
          display: 'flex',
          flexDirection: 'column',
        }}
      >
        {/* Top White Section */}
        <div style={{
          flex: '1',
          backgroundColor: '#ffffff',
          padding: '20px',
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'space-between',
        }}>
          <div>
            <div style={{
              fontSize: '24px',
              fontWeight: 'bold',
              color: '#7c3aed',
              marginBottom: '8px',
              letterSpacing: '1px',
            }}>
              SQUADLOG
            </div>
            <div style={{
              fontSize: '14px',
              color: '#7c3aed',
              marginBottom: '12px',
              fontWeight: 600,
            }}>
              EMPLOYEE ID CARD
            </div>
            <div style={{
              fontSize: '12px',
              color: '#7c3aed',
              marginBottom: '4px',
            }}>
              {teamMember.employeeId || 'N/A'}
            </div>
          </div>
          
          <div style={{
            display: 'grid',
            gridTemplateColumns: '1fr 1fr',
            gap: '8px',
            fontSize: '10px',
            color: '#7c3aed',
            marginTop: 'auto',
          }}>
            <div>
              <div style={{ fontWeight: 600, marginBottom: '2px' }}>Name</div>
              <div>{fullName}</div>
            </div>
            <div>
              <div style={{ fontWeight: 600, marginBottom: '2px' }}>Position</div>
              <div>{teamMember.position || 'N/A'}</div>
            </div>
            <div>
              <div style={{ fontWeight: 600, marginBottom: '2px' }}>Department</div>
              <div>{departmentName || 'N/A'}</div>
            </div>
            <div>
              <div style={{ fontWeight: 600, marginBottom: '2px' }}>Status</div>
              <div>{getStatusBadge(teamMember.status)}</div>
            </div>
          </div>
        </div>

        {/* Purple Wavy Separator */}
        <div style={{
          height: '20px',
          background: 'linear-gradient(135deg, #7c3aed 0%, #9333ea 100%)',
          position: 'relative',
          overflow: 'hidden',
        }}>
          <svg style={{ position: 'absolute', bottom: 0, width: '100%', height: '100%' }} viewBox="0 0 400 20" preserveAspectRatio="none">
            <path d="M0,10 Q100,0 200,10 T400,10 L400,20 L0,20 Z" fill="#7c3aed" />
            <path d="M0,15 Q100,5 200,15 T400,15 L400,20 L0,20 Z" fill="#9333ea" />
          </svg>
        </div>

        {/* Bottom Black Section with QR Codes */}
        <div style={{
          flex: '0 0 80px',
          backgroundColor: '#000000',
          padding: '12px 20px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          gap: '16px',
        }}>
          {/* QR Code Placeholder 1 */}
          <div style={{
            width: '56px',
            height: '56px',
            backgroundColor: '#ffffff',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: '8px',
            color: '#000000',
            fontWeight: 'bold',
          }}>
            QR 1
          </div>
          {/* QR Code Placeholder 2 */}
          <div style={{
            width: '56px',
            height: '56px',
            backgroundColor: '#ffffff',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: '8px',
            color: '#000000',
            fontWeight: 'bold',
          }}>
            QR 2
          </div>
        </div>
      </div>
    );
  }

  // Back Side Design
  return (
    <div
      id="id-card-back"
      style={{
        width: '400px',
        height: '250px',
        borderRadius: '8px',
        boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.25)',
        overflow: 'hidden',
        position: 'relative',
        fontFamily: 'system-ui, -apple-system, sans-serif',
        display: 'flex',
        flexDirection: 'column',
        background: 'linear-gradient(135deg, #1e1b4b 0%, #7c3aed 100%)',
      }}
    >
      {/* Top Section with Circular Photo */}
      <div style={{
        padding: '16px 20px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        position: 'relative',
      }}>
        <div style={{
          width: '100px',
          height: '100px',
          borderRadius: '50%',
          border: '4px solid #7c3aed',
          overflow: 'hidden',
          backgroundColor: '#ffffff',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          boxShadow: '0 4px 6px rgba(0, 0, 0, 0.3)',
          position: 'relative',
          zIndex: 2,
        }}>
          {teamMember.profileImage ? (
            <img
              src={teamMember.profileImage}
              alt={fullName}
              style={{
                width: '100%',
                height: '100%',
                objectFit: 'cover'
              }}
              onError={(e) => {
                e.target.style.display = 'none';
                if (e.target.nextSibling) {
                  e.target.nextSibling.style.display = 'flex';
                }
              }}
            />
          ) : null}
          <div
            style={{
              width: '100%',
              height: '100%',
              display: teamMember.profileImage ? 'none' : 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              backgroundColor: '#ffffff',
              color: '#374151',
              fontSize: '32px',
              fontWeight: 'bold'
            }}
          >
            {initials}
          </div>
        </div>
      </div>

      {/* Middle Section with Name and Info */}
      <div style={{
        flex: 1,
        backgroundColor: '#000000',
        padding: '16px 20px',
        display: 'flex',
        flexDirection: 'column',
        gap: '12px',
      }}>
        {/* Name and Badge */}
        <div style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
        }}>
          <div>
            <div style={{
              fontSize: '28px',
              fontWeight: 'bold',
              color: '#ffffff',
              marginBottom: '4px',
            }}>
              {fullName}
            </div>
            <div style={{
              fontSize: '12px',
              color: '#ffffff',
              opacity: 0.9,
            }}>
              {teamMember.position || 'Employee'}
            </div>
          </div>
          {teamMember.employeeId && (
            <div style={{
              backgroundColor: '#7c3aed',
              color: '#ffffff',
              padding: '6px 10px',
              borderRadius: '4px',
              fontSize: '12px',
              fontWeight: 'bold',
            }}>
              {teamMember.employeeId}
            </div>
          )}
        </div>

        {/* Contact Information with Icons */}
        <div style={{
          display: 'flex',
          flexDirection: 'column',
          gap: '8px',
          fontSize: '11px',
          color: '#ffffff',
        }}>
          {teamMember.email && (
            <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
              <span style={{ fontSize: '14px' }}>✉</span>
              <span>{teamMember.email}</span>
            </div>
          )}
          {teamMember.phone && (
            <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
              <span style={{ fontSize: '14px' }}>📞</span>
              <span>{teamMember.phone}</span>
            </div>
          )}
          {departmentName && (
            <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
              <span style={{ fontSize: '14px' }}>🏢</span>
              <span>{departmentName}</span>
            </div>
          )}
          {teamMember.role && (
            <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
              <span style={{ fontSize: '14px' }}>👤</span>
              <span>{teamMember.role}</span>
            </div>
          )}
        </div>
      </div>

      {/* Bottom Section with QR Codes */}
      <div style={{
        height: '70px',
        backgroundColor: '#000000',
        padding: '10px 20px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        gap: '16px',
        borderTop: '1px solid rgba(255, 255, 255, 0.1)',
      }}>
        {/* QR Code Placeholder 1 */}
        <div style={{
          width: '50px',
          height: '50px',
          backgroundColor: '#ffffff',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontSize: '8px',
          color: '#000000',
          fontWeight: 'bold',
        }}>
          QR 1
        </div>
        {/* QR Code Placeholder 2 */}
        <div style={{
          width: '50px',
          height: '50px',
          backgroundColor: '#ffffff',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontSize: '8px',
          color: '#000000',
          fontWeight: 'bold',
        }}>
          QR 2
        </div>
      </div>
    </div>
  );
}
